                let s_prime = NetworkState {
                    in_flight: s.in_flight.remove(msg_ops.recv->0).add(msg_ops.send)
                };
                (s_prime, ())
            } else {
                let s_prime = NetworkState {
                    in_flight: s.in_flight.add(msg_ops.send)
                };
                (s_prime, ())
            }
        },
    }
}

